window.fetchClinicSession=async function(url,options){return fetch(url,options||{});};
window.getClinicProviderKeys=function(){return {gemini:document.getElementById('cfg-gemini-key')?.value?.trim()||'',groq:document.getElementById('cfg-groq-key')?.value?.trim()||'',openrouter:document.getElementById('cfg-openrouter-key')?.value?.trim()||''};};
window.clinicPendingAttachments=[];window.clinicPendingFileNames=[];
window._clinicPdfJsPromise=null;
window.loadClinicPdfJs=function(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);if(window._clinicPdfJsPromise)return window._clinicPdfJsPromise;window._clinicPdfJsPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';s.onload=()=>{if(window.pdfjsLib){window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(window.pdfjsLib);}else reject(Error('تعذر تحميل قارئ PDF'));};s.onerror=()=>reject(Error('تعذر تحميل قارئ PDF؛ تحقق من الاتصال'));document.head.appendChild(s);});return window._clinicPdfJsPromise;};
window.readClinicPdfText=async function(file){const lib=await window.loadClinicPdfJs(),buf=await file.arrayBuffer(),pdf=await lib.getDocument({data:buf}).promise,parts=[];for(let n=1;n<=Math.min(pdf.numPages,12);n++){const page=await pdf.getPage(n),content=await page.getTextContent();parts.push(content.items.map(x=>x.str).join(' '));if(parts.join('\n').length>35000)break;}return {pdf,text:parts.join('\n').slice(0,35000)};};
