window.callAIRequest=async function(prompt,system,model,context,attachments){const r=await window.fetchClinicSession('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:String(prompt||''),systemPrompt:String(system||''),model:model||'auto',keys:window.getClinicProviderKeys(),attachments:attachments||[],clinicContext:context?'\n\nالسياق المحدد:\n'+JSON.stringify(context):''})}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'فشل طلب الذكاء الاصطناعي.');return {result:d.result||'',provider:d.provider||model||'AI'};};
window.callAI=async function(prompt,system){let model=window.AppState.settings.ai.selectedMode||'auto';if(model==='local'){if((window.clinicPendingAttachments||[]).length)throw Error('المحرك المحلي لا يدعم تحليل المرفقات. اختر نموذجاً اجتاز الاختبار.');return {result:callLocalOfflineAI(String(prompt),system),provider:'محرك محلي محدود — ليس نموذجاً لغوياً'};}const needsVision=(window.clinicPendingAttachments||[]).some(a=>a.type==='image');if(needsVision){const gm=window.AI_MODELS_CATALOG.find(m=>m.provider==='gemini');if(!gm)throw Error('تحليل الصور وPDF المصوّر يحتاج مفتاح Gemini ونموذج Gemini اجتاز الاختبار.');if(model==='auto'||!window.AI_MODELS_CATALOG.some(m=>m.id===model&&m.provider==='gemini'))model=gm.id;}if(model==='auto'){if(!window.AI_MODELS_CATALOG.length)throw Error('افتح الإعدادات واضغط «فحص النماذج باستجابة فعلية» أولاً.');model=window.AI_MODELS_CATALOG[0].id;}else if(!window.AI_MODELS_CATALOG.some(m=>m.id===model))throw Error('هذا النموذج لم يجتز اختبار الاستجابة الحالي. أعد فحص النماذج واختر نموذجاً ناجحاً.');const p=String(prompt||''),rs=window.AppState.receipts||[],iv=window.AppState.inventory||[],ex=window.AppState.expenses||[],ctx=window.buildRelevantClinicContext(p),patientSpecificQuery=/مريض|للمريض|المريضة|رقمه|رقمها|هاتفه|هاتفها/.test(p),all=!patientSpecificQuery&&/جميع|كافة|كل السندات|تقرير شامل|مراجعة كاملة|بالتفصيل/.test(p);let src=null,label='',size=25;if(all&&/سند|سندات|إيراد|ايراد|مقبوض|ديون|مديون|دين|حساب/.test(p)&&rs.length>25){src=rs;label='السندات';}else if(all&&/مخزون|مواد|مادة|نفاد|ناقص|كمية/.test(p)&&iv.length>40){src=iv;label='المخزون';size=40;}else if(all&&/مصروف|مصاريف|ربح|مالية|تقرير/.test(p)&&ex.length>25){src=ex;label='المصروفات';}if(src){const batches=[];for(let i=0;i<src.length;i+=size){const rows=src.slice(i,i+size).map(x=>label==='السندات'?{receiptNo:x.receiptNo,date:x.date,patientName:x.patientName,totalAmount:x.totalAmount,paidAmount:x.paidAmount,remainingAmount:x.remainingAmount,currency:x.currency}:label==='المخزون'?{name:x.name,qty:x.qty,unit:x.unit||'غير محدد',minQty:x.minQty}:{title:x.title,amount:x.amount,date:x.date,currency:x.currency}),ans=await window.callAIRequest('لخص هذه الدفعة فقط بدقة. لا تدّع أنها كل السجلات. الطلب: '+p,'أنت مدقق بيانات؛ لا تخترع.',model,{dataset:label,batch:Math.floor(i/size)+1,totalBatches:Math.ceil(src.length/size),records:rows});batches.push({batch:Math.floor(i/size)+1,count:rows.length,summary:ans.result});}return window.callAIRequest('أصدر التقرير النهائي اعتماداً على ملخصات جميع الدفعات. اذكر العدد المعالج والقيود. الطلب: '+p,'أنت مدقق عيادة. لا تسمّ صافي المقبوضات ربحاً محاسبياً دون تكاليف المواد.',model,{dataset:label,totalRecords:src.length,batches});}const attachments=window.clinicPendingAttachments||[];window.clinicPendingAttachments=[];window.clinicPendingFileNames=[];const fl=document.getElementById('chat-file-input');if(fl)fl.value='';const preview=document.getElementById('chat-attachment-preview');if(preview)preview.textContent='';return window.callAIRequest(p,(system||'أنت مساعد إداري لعيادة الأسنان.')+'\nاعتمد على السجلات المحددة فقط، ولا تخمن هوية مريض من تشابه جزئي، ولا تدّع الاطلاع على سجلات لم تُرسل.',model,ctx,attachments);};
window.appendChatMsg=function(msg,sender,loading){const c=document.getElementById('chat-messages-container');if(!c)return '';const id='m_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),row=document.createElement('div'),avatar=document.createElement('div'),bubble=document.createElement('div');row.id=id;row.className='clinic-chat-row '+(sender==='user'?'clinic-chat-user':'clinic-chat-ai');avatar.className='clinic-chat-avatar';avatar.textContent=sender==='user'?'أنت':'AI';bubble.className='clinic-chat-bubble '+(sender==='user'?'clinic-chat-bubble-user':'clinic-chat-bubble-ai');bubble.dir='auto';bubble.textContent=String(msg||'');if(loading){const s=document.createElement('span');s.className='clinic-chat-loading';s.textContent='  ⏳ جارٍ التفكير…';bubble.appendChild(s);}row.appendChild(avatar);row.appendChild(bubble);c.appendChild(row);c.scrollTop=c.scrollHeight;return id;};
window.clinicVoiceActive=false;window.clinicRecognition=null;window.clinicCurrentAudio=null;
window.speakClinicText=async function(text){const engine=document.getElementById('chat-speech-engine')?.value||'phone',clean=String(text||'').replace(/[\x60*_#>]/g,' ').slice(0,5000);if(engine==='phone'){if(!('speechSynthesis'in window)){showToast('محرك صوت الهاتف غير مدعوم.','error');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(clean);u.lang='ar-SA';u.rate=1;u.onend=()=>{if(window.clinicVoiceActive)window.startClinicListening();};window.speechSynthesis.speak(u);return;}const parts=clean.match(/[^.!؟\n]{1,175}(?:[.!؟\n]|$)/g)||[clean];let idx=0;async function next(){if(idx>=parts.length){if(window.clinicVoiceActive)window.startClinicListening();return;}const seg=parts[idx++].trim();if(!seg)return next();try{const r=await window.fetchClinicSession('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:seg.slice(0,200),voice:document.getElementById('chat-ai-voice')?.value||'fahad',keys:window.getClinicProviderKeys()})});if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error||'تعذر توليد الصوت');}const blob=await r.blob(),url=URL.createObjectURL(blob),a=new Audio(url);window.clinicCurrentAudio=a;a.onended=()=>{URL.revokeObjectURL(url);next();};a.onerror=()=>{URL.revokeObjectURL(url);showToast('تعذر تشغيل صوت النموذج.','error');};await a.play();}catch(e){showToast('صوت النموذج: '+e.message,'error');window.clinicVoiceActive=false;}}await next();};
window.startClinicListening=function(){if(!window.clinicVoiceActive)return;const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec){showToast('التعرف الصوتي غير مدعوم في هذا المتصفح.','error');window.stopClinicVoiceConversation();return;}try{const rec=new Rec();window.clinicRecognition=rec;rec.lang='ar-YE';rec.continuous=false;rec.interimResults=false;const status=document.getElementById('voice-conversation-status');if(status)status.textContent='أستمع إليك…';rec.onresult=e=>{const t=e.results?.[0]?.[0]?.transcript||'';if(!t.trim())return;const i=document.getElementById('chat-input-text');i.value=t;if(status)status.textContent='أرسل الكلام إلى المساعد…';window.sendChatMessage();};rec.onerror=()=>{if(window.clinicVoiceActive){if(status)status.textContent='تعذر التقاط الصوت؛ أعد المحاولة';setTimeout(()=>{if(window.clinicVoiceActive)window.startClinicListening();},900);}};rec.onend=()=>{if(window.clinicVoiceActive&&!window.clinicSpeakingNow&&status&&status.textContent==='أستمع إليك…')setTimeout(()=>{if(window.clinicVoiceActive)window.startClinicListening();},400);};rec.start();}catch(e){if(window.clinicVoiceActive)setTimeout(()=>window.startClinicListening(),800);}};
window.startClinicVoiceConversation=function(){window.clinicVoiceActive=true;const s=document.getElementById('voice-conversation-status');if(s)s.textContent='بدء المحادثة الصوتية…';window.startClinicListening();};
window.stopClinicVoiceConversation=function(){window.clinicVoiceActive=false;try{window.clinicRecognition?.stop();}catch(e){}try{window.speechSynthesis?.cancel();}catch(e){}try{window.clinicCurrentAudio?.pause();}catch(e){}const s=document.getElementById('voice-conversation-status');if(s)s.textContent='المحادثة الصوتية متوقفة';};
window.sendChatMessage=async function(){const inp=document.getElementById('chat-input-text'),t=inp?.value?.trim();if(!t)return;window.clinicSpeakingNow=false;appendChatMsg(t,'user');inp.value='';const id=appendChatMsg('جارٍ تحديد البيانات ذات الصلة ثم طلب الرد…','ai',true),send=document.getElementById('chat-send-button');if(send)send.disabled=true;try{const r=await window.callAI(t,'أنت المساعد التنفيذي لعيادة الأسنان. استخدم السجلات المرتبطة فقط واذكر حدودها بوضوح.');document.getElementById(id)?.remove();appendChatMsg(r.result||'لم يصل رد نصي.','ai');const badge=document.getElementById('chat-last-model-badge');if(badge)badge.textContent=r.provider||'AI';if(document.getElementById('chat-auto-tts-toggle')?.checked){window.clinicSpeakingNow=true;await window.speakClinicText(r.result);window.clinicSpeakingNow=false;}else if(window.clinicVoiceActive){setTimeout(()=>{if(window.clinicVoiceActive)window.startClinicListening();},300);}}catch(e){document.getElementById(id)?.remove();appendChatMsg('تعذر إكمال الطلب: '+e.message,'ai');}finally{if(send)send.disabled=false;}};
