/* Preserve inventory accounting when a receipt is created or its services change. */
window.ClinicDB.saveReceipt=function(d){
 const list=window.AppState.receipts||[],idx=list.findIndex(r=>r.id===d.id),old=idx>=0?list[idx]:null;
 if(!d.id)d.id='REC_'+Date.now()+'_'+Math.random().toString(36).slice(2,7);
 if(list.some(r=>String(r.receiptNo)===String(d.receiptNo)&&r.id!==d.id))throw Error('رقم السند مستخدم بالفعل.');
 const total=Number(d.totalAmount),paid=Number(d.paidAmount);
 if(!Number.isFinite(total)||!Number.isFinite(paid)||total<0||paid<0||paid>total)throw Error('الإجمالي والمدفوع يجب أن يكونا صالحين والمدفوع لا يتجاوز الإجمالي.');
 const changes=[];
 if(window.AppState.settings.features.autoInventory){
  (window.AppState.inventory||[]).forEach(item=>{
   const linked=String(item.linkedService||'');
   const wasUsed=!!old&&!!linked&&(old.services||[]).includes(linked);
   const nowUsed=!!linked&&(d.services||[]).includes(linked);
   if(wasUsed!==nowUsed){const delta=nowUsed?-1:1;if(Number(item.qty||0)+delta<0)throw Error('المخزون لا يكفي للمادة: '+item.name);changes.push({item,delta});}
  });
 }
 d.remainingAmount=total-paid;d.updatedAt=new Date().toISOString();
 changes.forEach(x=>{x.item.qty=Number(x.item.qty||0)+x.delta;window.ClinicDB.recordInventoryMovement(x.item.id,x.delta<0?'consume':'restore',Math.abs(x.delta),'تسوية تلقائية مع السند '+d.receiptNo);});
 if(old)list[idx]=Object.assign({},old,d);else{d.createdAt=new Date().toISOString();list.unshift(d);}
 window.saveReceiptsState();if(changes.length)window.saveInventoryState();return d;
};


