/* Encrypted JSONBin backup/restore. Provider credentials remain in form fields only. */
window.clinicCryptoKey=async function(pass,salt){const enc=new TextEncoder(),base=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);};
window.clinicBackupPayload=function(){return {app:'ALSSAEDY_CLINIC_ERP',schemaVersion:1,exportedAt:new Date().toISOString(),settings:(()=>{const s=JSON.parse(JSON.stringify(window.AppState.settings));s.ai.geminiKey='';s.ai.groqKey='';s.ai.openrouterKey='';if(s.cloud)s.cloud.apiKey='';return s;})(),receipts:window.AppState.receipts||[],inventory:window.AppState.inventory||[],expenses:window.AppState.expenses||[],inventoryMovements:JSON.parse(localStorage.getItem('alssaedy_erp_movements_v1')||'[]')};};
window.syncDataToCloud=async function(){const key=document.getElementById('cfg-cloud-key')?.value?.trim(),binInput=document.getElementById('cfg-cloud-bin'),bin=binInput?.value?.trim();if(!key){showToast('أدخل مفتاح JSONBin في إعدادات السحابة.','error');return;}const pass=window.prompt('أنشئ كلمة مرور تشفير قوية للنسخة السحابية. لن تُرفع البيانات دون تشفير، ولا يمكن الاستعادة دون هذه الكلمة.');if(!pass||pass.length<10){showToast('كلمة التشفير يجب أن تكون 10 أحرف على الأقل.','error');return;}if(!confirm('ستُرفع نسخة مشفرة من سجلات المرضى والمالية إلى JSONBin. لا ترفعها إلا إلى حساب تثق به. متابعة؟'))return;try{const enc=new TextEncoder(),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),k=await window.clinicCryptoKey(pass,salt),plain=enc.encode(JSON.stringify(window.clinicBackupPayload())),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,plain),payload={app:'ALSSAEDY_CLINIC_ERP_ENCRYPTED',version:1,salt:Array.from(salt),iv:Array.from(iv),ciphertext:Array.from(new Uint8Array(cipher)),encryptedAt:new Date().toISOString()};const url=bin?'https://api.jsonbin.io/v3/b/'+encodeURIComponent(bin):'https://api.jsonbin.io/v3/b',r=await fetch(url,{method:bin?'PUT':'POST',headers:{'Content-Type':'application/json','X-Master-Key':key,'X-Bin-Name':'ALSSAEDY-CLINIC-ENCRYPTED-BACKUP','X-Bin-Private':'true'},body:JSON.stringify(payload)}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'JSONBin HTTP '+r.status);const id=d.metadata?.id||bin;if(id&&binInput){binInput.value=id;window.AppState.settings.cloud.binId=id;window.AppState.settings.cloud.apiKey='';window.saveSettingsState();}showToast('تم رفع نسخة مشفرة بنجاح. احتفظ بكلمة التشفير وBin ID.','success');}catch(e){showToast('فشل النسخ السحابي: '+e.message,'error');}};
window.syncDataFromCloud=async function(){const key=document.getElementById('cfg-cloud-key')?.value?.trim(),bin=document.getElementById('cfg-cloud-bin')?.value?.trim();if(!key||!bin){showToast('أدخل JSONBin Key وBin ID أولاً.','error');return;}const pass=window.prompt('أدخل كلمة مرور تشفير النسخة السحابية.');if(!pass)return;try{const r=await fetch('https://api.jsonbin.io/v3/b/'+encodeURIComponent(bin)+'/latest',{headers:{'X-Master-Key':key,'X-Bin-Meta':'false'}}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'JSONBin HTTP '+r.status);const p=d.record||d;if(p.app!=='ALSSAEDY_CLINIC_ERP_ENCRYPTED'||p.version!==1)throw Error('هذه النسخة ليست نسخة مشفرة متوافقة.');const salt=new Uint8Array(p.salt),iv=new Uint8Array(p.iv),cipher=new Uint8Array(p.ciphertext),k=await window.clinicCryptoKey(pass,salt),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},k,cipher),data=JSON.parse(new TextDecoder().decode(plain));if(data.app!=='ALSSAEDY_CLINIC_ERP'||!data.settings||!Array.isArray(data.receipts)||!Array.isArray(data.inventory)||!Array.isArray(data.expenses))throw Error('بنية البيانات المستعادة غير صحيحة.');if(!confirm('سيتم تنزيل نسخة احتياطية محلية ثم استبدال بيانات هذا المتصفح. متابعة؟'))return;window.downloadClinicBackup();window.AppState.settings=data.settings;window.AppState.settings.ai.geminiKey='';window.AppState.settings.ai.groqKey='';window.AppState.settings.ai.openrouterKey='';window.AppState.settings.cloud.apiKey='';window.AppState.receipts=data.receipts;window.AppState.inventory=data.inventory;window.AppState.expenses=data.expenses;localStorage.setItem('alssaedy_erp_movements_v1',JSON.stringify(Array.isArray(data.inventoryMovements)?data.inventoryMovements:[]));window.saveSettingsState();window.saveReceiptsState();window.saveInventoryState();window.saveExpensesState();window.AppState.selectedServices=new Set();window.loadSettingsToUI();window.initAppUI();showToast('تم فك التشفير والاستعادة بنجاح.','success');}catch(e){showToast('فشل الاستعادة: تحقق من كلمة التشفير وBin ID. '+e.message,'error');}};


/* Missing search/filter and inventory audit actions referenced by the UI. */
window.renderRecordsTable=function(){const tb=document.getElementById('records-table-body');if(!tb)return;const q=(document.getElementById('search-records-input')?.value||'').trim().toLocaleLowerCase(),filter=document.getElementById('filter-records-debt')?.value||'all',all=window.AppState.receipts||[],rows=all.filter(r=>{const hay=[r.receiptNo,r.patientName,r.patientPhone,r.date,...(r.services||[])].join(' ').toLocaleLowerCase();if(q&&!hay.includes(q))return false;if(filter==='debt'&&Number(r.remainingAmount)<=0)return false;if(filter==='paid'&&Number(r.remainingAmount)>0)return false;return true;});const nav=document.getElementById('nav-debts-count');if(nav)nav.textContent=all.filter(r=>Number(r.remainingAmount)>0).length;if(!rows.length){tb.innerHTML='<tr><td colspan="9" class="text-center py-4 text-slate-500">لا توجد نتائج مطابقة</td></tr>';return;}tb.innerHTML=rows.map(r=>'<tr><td class="p-2">#'+escapeHtml(r.receiptNo)+'</td><td class="p-2">'+escapeHtml(r.date)+'</td><td class="p-2">'+escapeHtml(r.patientName)+'</td><td class="p-2">'+escapeHtml(r.patientPhone||'-')+'</td><td class="p-2">'+escapeHtml((r.services||[]).join('، '))+'</td><td class="p-2">'+escapeHtml(Number(r.totalAmount)||0)+'</td><td class="p-2 text-emerald-400">'+escapeHtml(Number(r.paidAmount)||0)+'</td><td class="p-2 text-rose-400">'+escapeHtml(Number(r.remainingAmount)||0)+'</td><td class="p-2"><button type="button" class="text-rose-400" data-delete-receipt="'+escapeHtml(r.id)+'">حذف</button></td></tr>').join('');tb.querySelectorAll('[data-delete-receipt]').forEach(b=>b.onclick=()=>{if(!confirm('حذف السند نهائياً؟'))return;window.ClinicDB.deleteReceipt(b.dataset.deleteReceipt);window.renderRecordsTable();window.renderRecords();window.updateDash();});};
window.runInventoryAuditAI=async function(){const out=document.getElementById('inventory-ai-summary');if(!out)return;out.textContent='جارٍ فحص المخزون والمصروفات…';try{const inv=window.AppState.inventory||[],exp=window.AppState.expenses||[],low=inv.filter(x=>Number(x.qty)<=Number(x.minQty)),ctx={inventory:{totalItems:inv.length,lowStockCount:low.length,lowStockItems:low.slice(0,40).map(x=>({name:x.name,qty:x.qty,minQty:x.minQty,unit:x.unit||'غير محدد'})),items:inv.slice(0,35).map(x=>({name:x.name,qty:x.qty,minQty:x.minQty,unit:x.unit||'غير محدد',cost:x.cost,price:x.price}))},expenses:{count:exp.length,total:exp.reduce((a,x)=>a+(Number(x.amount)||0),0),recent:exp.slice(0,25).map(x=>({title:x.title,amount:x.amount,date:x.date}))},receipts:{count:(window.AppState.receipts||[]).length,paid:(window.AppState.receipts||[]).reduce((a,x)=>a+(Number(x.paidAmount)||0),0),remaining:(window.AppState.receipts||[]).reduce((a,x)=>a+(Number(x.remainingAmount)||0),0)}};if(!window.AI_MODELS_CATALOG.length)throw Error('افحص النماذج من الإعدادات أولاً.');const r=await window.callAI('أجرِ تدقيقاً تشغيلياً للمخزون والمصروفات والذمم باستخدام البيانات المرتبطة بالسؤال فقط. حدد النواقص والمخاطر والتوصيات، ولا تسمّ المقبوضات ربحاً صافياً ولا تستنتج هامش ربح دون تكلفة موثقة. اذكر حدود البيانات المتاحة.','أنت مدقق عمليات لعيادة أسنان. لا تخترع بيانات ولا تخلط العملات.');out.textContent=r.result;showToast('اكتمل فحص المخزون والمصروفات عبر '+r.provider,'success');}catch(e){out.textContent='تعذر إكمال الفحص: '+e.message;showToast(e.message,'error');}};
window.deleteReceipt=function(id){if(!confirm('هل تريد حذف السند نهائياً؟'))return;window.ClinicDB.deleteReceipt(id);window.renderRecordsTable();window.renderRecords();window.updateDash();};
window.deleteExpense=function(id){if(!confirm('هل تريد حذف المصروف نهائياً؟'))return;window.ClinicDB.deleteExpense(id);window.renderInv();window.updateDash();};


/* Deleting a receipt reverses linked stock consumption to keep the ledger balanced. */
window.ClinicDB.deleteReceipt=function(id){const list=window.AppState.receipts||[],idx=list.findIndex(r=>r.id===id);if(idx<0)return false;const rec=list[idx],changes=[];if(window.AppState.settings.features.autoInventory){(window.AppState.inventory||[]).forEach(item=>{const linked=String(item.linkedService||'');if(linked&&(rec.services||[]).includes(linked)){item.qty=Number(item.qty||0)+1;changes.push(item);window.ClinicDB.recordInventoryMovement(item.id,'restore',1,'عكس استهلاك السند المحذوف '+rec.receiptNo);}});}list.splice(idx,1);window.saveReceiptsState();if(changes.length)window.saveInventoryState();return true;};
window.saveAndPrintReceipt=function(mode){try{const d=window.saveReceiptOnly();if(!d)return;document.body.classList.toggle('print-mode-thermal',mode==='thermal');setTimeout(()=>window.print(),150);}catch(e){showToast('تعذر حفظ/طباعة السند: '+e.message,'error');}};


window.renderSettingsServices=function(){const host=document.getElementById('settings-services-list');if(!host)return;host.replaceChildren();(window.AppState.settings.services||[]).forEach(s=>{const card=document.createElement('div');card.dataset.serviceCard=s.id;card.className='bg-slate-950 border border-slate-800 rounded-xl p-3 space-y-2';const mk=(label,type,key,val)=>{const wrap=document.createElement('label');wrap.className='block text-[11px] text-slate-400';wrap.textContent=label;const input=document.createElement('input');input.type=type;input.dataset[key]='1';input.value=val==null?'':String(val);input.className='mt-1 w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-2 text-xs text-white';wrap.appendChild(input);card.appendChild(wrap);return input;};mk('اسم الخدمة','text','serviceName',s.name);mk('السعر الافتراضي','number','servicePrice',s.price).min='0';mk('كلمات مفتاحية (افصل بينها بفواصل)','text','serviceKeywords',(s.keywords||[]).join(', '));const del=document.createElement('button');del.type='button';del.className='text-rose-300 border border-rose-900 rounded-lg px-3 py-1.5 text-xs';del.textContent='حذف الخدمة';del.onclick=()=>{if(!confirm('حذف الخدمة "'+s.name+'"؟'))return;window.AppState.settings.services=window.AppState.settings.services.filter(x=>x.id!==s.id);window.saveSettingsState();window.renderSettingsServices();window.renderServices();};card.appendChild(del);card.querySelector('[data-service-name]').dataset.serviceName='1';card.querySelector('[data-service-price]').dataset.servicePrice='1';card.querySelector('[data-service-keywords]').dataset.serviceKeywords='1';host.appendChild(card);});};
window.addNewServiceRow=function(){const name=prompt('اسم الخدمة الجديدة:');if(!name||!name.trim())return;const price=Number(prompt('السعر الافتراضي (رقم فقط):','0'));if(!Number.isFinite(price)||price<0){showToast('السعر غير صالح.','error');return;}window.AppState.settings.services.push({id:'srv_'+Date.now(),name:name.trim(),price,keywords:[name.trim()]});window.saveSettingsState();window.renderSettingsServices();window.renderServices();showToast('أضيفت الخدمة. اضغط حفظ وتطبيق لحفظ بقية التعديلات.','success');};


/* Session-only API credentials: never copy provider keys into AppState or persistent storage. */
window.getClinicProviderKeys=function(){return {gemini:document.getElementById('cfg-gemini-key')?.value?.trim()||'',groq:document.getElementById('cfg-groq-key')?.value?.trim()||'',openrouter:document.getElementById('cfg-openrouter-key')?.value?.trim()||''};};
window.renderModelsTable=function(){
 const tb=document.getElementById('models-matrix-table-body');if(!tb)return;tb.replaceChildren();const ms=window.AI_MODELS_CATALOG||[];
 if(!ms.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.className='p-3 text-center text-slate-400';td.textContent='لم يجتز أي نموذج اختباراً بعد. أدخل المفتاح في الإعدادات ثم اضغط فحص النماذج.';tr.appendChild(td);tb.appendChild(tr);return;}
 ms.forEach((m,i)=>{const tr=document.createElement('tr');tr.className='hover:bg-slate-900';const status='نجح الاختبار · '+new Date(m.testedAt).toLocaleTimeString()+(m.limits?.requestsRemaining!==undefined?' · المتبقي '+m.limits.requestsRemaining:'');[String(i+1),m.provider.toUpperCase(),m.name,m.specialty,m.costClass+' — '+status].forEach(v=>{const td=document.createElement('td');td.className='p-2 align-top';td.textContent=v;tr.appendChild(td);});const td=document.createElement('td');td.className='p-2 text-center';const b=document.createElement('button');b.type='button';b.className='bg-cyan-700 hover:bg-cyan-600 rounded-lg px-3 py-1.5 text-xs';b.textContent='اختيار';b.onclick=()=>{window.AppState.settings.ai.selectedMode=m.id;const q=document.getElementById('quick-model-select');if(q)q.value=m.id;window.saveSettingsState();showToast('تم اختيار '+m.name,'success');};td.appendChild(b);tr.appendChild(td);tb.appendChild(tr);});
};
window.refreshVerifiedModels=async function(){
 const keys=window.getClinicProviderKeys(),status=document.getElementById('models-health-status'),tb=document.getElementById('models-matrix-table-body'),button=document.querySelector('#tab-settings button[onclick="testAndDiscoverAllModels()"]');
 if(!Object.values(keys).some(Boolean)){showToast('أدخل مفتاح مزود واحداً على الأقل في الإعدادات.','error');if(status)status.textContent='أدخل مفاتيحك أولاً';return;}
 if(status)status.textContent='جارٍ إرسال طلب اختبار حقيقي لكل نموذج…';if(button)button.disabled=true;
 if(tb){tb.replaceChildren();const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.className='p-3 text-center';td.textContent='جارٍ اختبار الاستجابة. قد يستهلك كل اختبار طلباً من حصتك.';tr.appendChild(td);tb.appendChild(tr);}
 try{
  const r=await fetch('/api/models',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({keys})}),d=await r.json().catch(()=>({}));
  if(!r.ok)throw Error(d.error||'تعذر فحص النماذج.');
  window.AI_MODELS_CATALOG=d.models||[];window.clinicModelCache=d;
  const q=document.getElementById('quick-model-select'),old=window.AppState.settings.ai.selectedMode||'auto';
  if(q){q.replaceChildren();const add=(v,t)=>{const o=document.createElement('option');o.value=v;o.textContent=t;q.appendChild(o);};add('auto','🤖 تلقائي: النماذج المجتازة فقط');window.AI_MODELS_CATALOG.forEach(m=>add(m.id,m.name+' · '+m.costClass));add('local','محلي دون اتصال (قدرات محدودة)');q.value=old==='local'||old==='auto'||window.AI_MODELS_CATALOG.some(m=>m.id===old)?old:'auto';window.AppState.settings.ai.selectedMode=q.value;}
  window.renderModelsTable();if(status)status.textContent='اجتاز الاختبار: '+window.AI_MODELS_CATALOG.length+' نموذجاً';
  ['gemini','groq','openrouter'].forEach(k=>{const dot=document.getElementById('dot-'+k);if(dot){dot.textContent=keys[k]?'تم إدخال المفتاح':'لم يُدخل المفتاح';dot.className='text-[10px] px-2 py-0.5 rounded '+(keys[k]?'bg-emerald-900 text-emerald-300':'bg-slate-800 text-slate-400');}});
  if(!window.AI_MODELS_CATALOG.length)showToast('لم ينجح أي نموذج. راجع المفتاح أو اسم النموذج أو الحصة.','error');else showToast('تم اختبار النماذج؛ المعروض هو ما استجاب الآن فقط.','success');
 }catch(e){window.AI_MODELS_CATALOG=[];window.renderModelsTable();if(status)status.textContent='فشل الاختبار';showToast(e.message,'error');}
 finally{if(button)button.disabled=false;}
};
window.testAndDiscoverAllModels=window.refreshVerifiedModels;
window.callAIRequest=async function(prompt,system,model,context,attachments){
 const keys=window.getClinicProviderKeys(),files=Array.isArray(attachments)?attachments:[],texts=files.filter(a=>a.type==='text').map(a=>'[محتوى الملف: '+String(a.name||'مرفق')+']\n'+String(a.text||'').slice(0,18000)),images=files.filter(a=>a.type==='image');
 let actualPrompt=String(prompt||'');if(texts.length)actualPrompt+='\n\nمحتوى المرفقات النصية:\n'+texts.join('\n\n').slice(0,40000);
 const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:actualPrompt,systemPrompt:String(system||''),model:model||'auto',keys,attachments:images,clinicContext:context?'\n\nالسياق المحدد:\n'+JSON.stringify(context):''})}),d=await r.json().catch(()=>({}));
 if(!r.ok)throw Error(d.error||'فشل طلب الذكاء الاصطناعي.');return {result:d.result||'',provider:d.provider||model||'AI'};
};
window.addEventListener('beforeunload',()=>{document.querySelectorAll('#cfg-gemini-key,#cfg-groq-key,#cfg-openrouter-key').forEach(e=>e.value='');});
document.addEventListener('DOMContentLoaded',function(){
 const settings=document.getElementById('tab-settings');
 if(settings){const note=document.createElement('div');note.className='bg-amber-950/50 border border-amber-700/60 rounded-xl p-3 text-xs leading-6 text-amber-100';note.textContent='مفاتيح API تُستخدم في الذاكرة أثناء هذه الجلسة فقط، ولا تُحفظ في التخزين المحلي. عند إعادة تحميل الصفحة أدخلها مجدداً. تُرسل عبر HTTPS إلى خدمة الاختبار/الطلب ثم إلى المزود المحدد؛ لا تشارك جهازاً غير موثوق. اختبار كل نموذج قد يستهلك طلباً من حصتك. نماذج Free ليست مضمونة التوفر أو الحصة اليومية.';const keys=document.getElementById('cfg-gemini-key');if(keys){const card=keys.closest('.grid');if(card)card.parentElement.insertBefore(note,card);}const clear=document.createElement('button');clear.type='button';clear.className='bg-rose-900 hover:bg-rose-800 text-white rounded-lg px-3 py-2 text-xs mt-2';clear.textContent='مسح مفاتيح API من الذاكرة';clear.onclick=()=>{['cfg-gemini-key','cfg-groq-key','cfg-openrouter-key'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});window.AI_MODELS_CATALOG=[];window.renderModelsTable();const st=document.getElementById('models-health-status');if(st)st.textContent='تم مسح المفاتيح من الواجهة';showToast('تم مسح المفاتيح من الواجهة.','success');};if(keys)keys.parentElement.parentElement.parentElement.appendChild(clear);}
 const fileInput=document.getElementById('chat-file-input');const chatInput=document.getElementById('chat-input-text');
 if(chatInput&&!fileInput){const wrap=document.createElement('div');wrap.className='flex flex-wrap gap-2 items-center mt-2';wrap.innerHTML='<label class="cursor-pointer bg-slate-800 hover:bg-slate-700 text-cyan-200 rounded-lg px-3 py-2 text-xs">📎 إرفاق ملفات وصور<input id="chat-file-input" type="file" multiple accept="image/*,.pdf,.txt,.csv,.json,.md,.docx,.xlsx,.xls" class="hidden"></label><span id="chat-attachment-preview" class="text-xs text-slate-400"></span>';chatInput.parentElement.insertAdjacentElement('afterend',wrap);document.getElementById('chat-file-input').addEventListener('change',e=>window.prepareClinicChatFiles(e.target.files));}
 const oldButton=document.querySelector('#tab-settings button[onclick="testAndDiscoverAllModels()"]');if(oldButton){oldButton.onclick=window.refreshVerifiedModels;oldButton.textContent='فحص النماذج باستجابة فعلية';}
});


/* Enforce that provider keys are never written to localStorage, even via legacy settings buttons. */
(function(){
 const originalLoad=window.loadSettingsToUI;
 window.saveSettingsState=function(){
  try{window.AppState.settings.ai.geminiKey='';window.AppState.settings.ai.groqKey='';window.AppState.settings.ai.openrouterKey='';}catch(e){}
  const copy=JSON.parse(JSON.stringify(window.AppState.settings||{}));
  if(copy.ai){copy.ai.geminiKey='';copy.ai.groqKey='';copy.ai.openrouterKey='';}
  if(copy.cloud){copy.cloud.apiKey='';}
  localStorage.setItem('alssaedy_erp_s_v2',JSON.stringify(copy));
 };
 if(typeof originalLoad==='function')window.loadSettingsToUI=function(){
  const keys=window.getClinicProviderKeys();originalLoad();
  ['gemini','groq','openrouter'].forEach(k=>{const el=document.getElementById('cfg-'+k+'-key');if(el&&keys[k])el.value=keys[k];});
 };
 const originalSaveAll=window.saveAllSettings;
 window.saveAllSettings=function(){
  const keys=window.getClinicProviderKeys();
  if(typeof originalSaveAll==='function')originalSaveAll();
  ['gemini','groq','openrouter'].forEach(k=>{const el=document.getElementById('cfg-'+k+'-key');if(el)el.value=keys[k];});
  ['gemini','groq','openrouter'].forEach(k=>{const el=document.getElementById('cfg-'+k+'-key');if(el)el.value=keys[k];});
  showToast('حُفظت إعدادات العيادة دون حفظ مفاتيح API؛ المفاتيح تبقى في الذاكرة لهذه الجلسة فقط.','success');
 };
})();
